function solve(n, k) {
  let dp = new Array(n).fill(0);
  dp[0] = 1;
  for (let s = 0; s < k; s++) {
    const next = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
      if (!dp[i]) continue;
      next[(i + 1) % n] += dp[i];
      next[(i - 1 + n) % n] += dp[i];
    }
    dp = next;
  }
  return dp[0];
}
